import sys, re, collections
f = sys.argv[1]
samples = []
cur = None
for line in open(f, errors='replace'):
    s = line.strip()
    if s.startswith('stackTrace = ['):
        cur = []
    elif s == ']' and cur is not None:
        samples.append(cur); cur = None
    elif cur is not None and s:
        m = re.match(r'(.*)\((.*)\) line: (\d+)', s)
        if m: cur.append((m.group(1), int(m.group(3))))
        elif s != '...': cur.append((s, 0))
        else: cur.append(('...', 0))
N = len(samples)
print('samples', N)
def short(fr): 
    n, l = fr
    n = n.replace('com.sun.fortress.scala_src.', '').replace('com.sun.fortress.', '')
    return '%s:%d' % (n, l)
ta = [s for s in samples if any('TypeAnalyzer.' in fr[0] for fr in s)]
print('with TypeAnalyzer frames', len(ta), '%.1f%%' % (100.0*len(ta)/N))
trunc = sum(1 for s in samples if len(s) >= 2048 or (s and s[-1][0]=='...'))
print('stacks at depth limit/truncated', trunc)
# inclusive counts of TypeAnalyzer/TypeSchemaAnalyzer/Overloading frames (count once per sample)
inc = collections.Counter()
for s in samples:
    seen = set()
    for fr in s:
        if ('types.TypeAnalyzer' in fr[0] or 'TypeSchemaAnalyzer' in fr[0] or 'Overloading' in fr[0] or 'StaticChecker' in fr[0]) :
            k = short(fr)
            if k not in seen: seen.add(k); inc[k]+=1
print('\n-- inclusive (once per sample), top 45')
for k, c in inc.most_common(45): print('%6d %5.1f%%  %s' % (c, 100.0*c/N, k))
# the Fortress frame that called the Walker (first non-Walker frame after a Walker frame from top)
wcall = collections.Counter()
for s in samples:
    if s and 'Walker' in s[0][0] or (len(s)>1 and any('Walker.walk' in fr[0] for fr in s[:3])):
        for fr in s:
            if 'Walker' in fr[0] or 'scala.' in fr[0] or 'nodes.' in fr[0] and 'scala_src' not in fr[0] or 'ASTGenHelper' in fr[0] or 'normalizer' in fr[0] or 'remover' in fr[0]:
                continue
            wcall[short(fr)] += 1; break
print('\n-- caller of the Walker at the top, top 20')
for k, c in wcall.most_common(20): print('%6d %5.1f%%  %s' % (c, 100.0*c/N, k))
# depth distribution: normConjunct frames per sample, pNorm frames, VarType bound pNorm
def cnt(s, pat): return sum(1 for fr in s if pat(fr))
dist = collections.Counter(cnt(s, lambda fr: fr[0].endswith('TypeAnalyzer.normConjunct')) for s in ta)
print('\n-- normConjunct frames per sample:', sorted(dist.items()))
dist = collections.Counter(cnt(s, lambda fr: fr[0].endswith('TypeAnalyzer.pExcInner')) for s in ta)
print('-- pExcInner frames per sample:', sorted(dist.items()))
dist = collections.Counter(len(s)//100*100 for s in ta)
print('-- stack length (by 100):', sorted(dist.items()))
# the outermost checker frame (bottom-most OverloadingChecker / TypeSchemaAnalyzer)
outer = collections.Counter()
for s in ta:
    for fr in reversed(s):
        if 'TypeSchemaAnalyzer' in fr[0] or 'OverloadingOracle' in fr[0]:
            outer[short(fr)] += 1; break
print('\n-- outermost schema/oracle frame, top 15')
for k, c in outer.most_common(15): print('%6d %5.1f%%  %s' % (c, 100.0*c/N, k))
EOF
cd /home/user/fortress-checkerspeed && python3 tmp/prof/analyze.py tmp/prof/part1-samples.txt

